/* crosswalk cards, r31. */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["31a"]=[{"q": "Which three demands make a product?", "a": "straight in the first slot, indifferent to order, positive", "w": ["straight, symmetric, bounded", "positive, finite, continuous", "straight in both slots, real, bounded"], "why": "Positivity: ⟨f, f⟩ > 0 for every f ≠ 0."}, {"q": "Under the area product on [0, 1], what is ‖x‖?", "a": "1/√3", "w": ["1/2", "1/3", "1"], "why": "‖x‖² = ∫₀¹ x² dx = 1/3."}, {"q": "f ⊥ g, ‖f‖ = 3, ‖g‖ = 4. What is ‖f + g‖?", "a": "5", "w": ["7", "1", "√7"], "why": "Square-sum: 9 + 16 = 25."}, {"q": "A line reads ‖f + g‖² = ‖f‖² + ‖g‖² for f ⊥ g. Which technique?", "a": "square-sum", "w": ["product-bound", "product-triangle", "turned-product"], "why": "The cross terms are 2⟨f, g⟩ = 0."}, {"q": "For lists of turning numbers, why does the plain dot fail?", "a": "(1, i) would have size 0", "w": ["it is not straight", "it is not indifferent to order", "it gives turning sizes"], "why": "1·1 + i·i = 0; the conjugate in the second slot mends it."}, {"q": "Over the turning numbers, ⟨f, 2i g⟩ equals what?", "a": "−2i⟨f, g⟩", "w": ["2i⟨f, g⟩", "2⟨f, g⟩", "−2⟨f, g⟩"], "why": "Turned-product: the second slot takes the conjugate of 2i."}, {"q": "A line reads |⟨f, g⟩| ≤ ‖f‖ ‖g‖. Which technique?", "a": "product-bound", "w": ["square-sum", "product-triangle", "closest-point"], "why": "Equality exactly when one is a multiple of the other."}, {"q": "Is ∫₋₁¹ x f(x)g(x) dx a product?", "a": "no: ⟨1, 1⟩ = 0", "w": ["yes: it is straight", "yes: it is indifferent to order", "no: it is not straight"], "why": "A weight must be above 0."}, {"q": "1 and x on [−1, 1]: what angle under the area product?", "a": "90°", "w": ["45°", "0°", "60°"], "why": "⟨1, x⟩ = ∫ x dx = 0."}, {"q": "Why does the angle between two functions always exist?", "a": "the product bound puts the cosine in [−1, 1]", "w": ["the triangle makes sizes positive", "every product is a dot", "functions are continuous"], "why": "cos θ = ⟨f, g⟩/(‖f‖ ‖g‖)."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["31b"]=[{"q": "‖e‖ = 1. What is the closest point of the line through e to f?", "a": "⟨f, e⟩e", "w": ["⟨f, e⟩f", "f − e", "‖f‖e"], "why": "The closest-point technique; the miss is ⊥ e."}, {"q": "g has size 2. What is the shadow of f on the line through g?", "a": "(⟨f, g⟩/4)g", "w": ["(⟨f, g⟩/2)g", "⟨f, g⟩g", "(⟨f, g⟩/16)g"], "why": "Divide by ‖g‖² = 4."}, {"q": "A line reads Pf = Σ⟨f, eₖ⟩eₖ for a right-angled list. Which technique?", "a": "shadow-sum", "w": ["closest-point", "miss-at-right-angles", "square-sum"], "why": "The miss is ⊥ every vector of W."}, {"q": "What is a right-angled list?", "a": "vectors of size 1, each ⊥ the others", "w": ["vectors at right angles of any size", "a free list", "a basis of the space"], "why": "Size 1 and pairwise ⊥."}, {"q": "Why is the shadow of eˣ on 1, x over [−1, 1] not the tangent line?", "a": "it is closest over the whole interval", "w": ["the tangent line is not straight", "eˣ has no tangent at 0", "the shadow passes through (0, 1)"], "why": "Pe^x ≈ 1.175 + 1.104x; the tangent fits only at 0."}, {"q": "For free v₁, …, vₖ, the closest c solves which samenesses?", "a": "Gc = b, Gᵢⱼ = ⟨vⱼ, vᵢ⟩", "w": ["c = b", "Gb = c", "Gc = 0"], "why": "Miss-at-right-angles; bᵢ = ⟨f, vᵢ⟩."}, {"q": "Why is G undoable when the vⱼ are free?", "a": "Gc = 0 gives ‖Σcⱼvⱼ‖ = 0, so c = 0", "w": ["G is symmetric", "G is square", "G has positive entries"], "why": "Free means only c = 0 builds 0."}, {"q": "The best line through points is the shadow of y on which piece?", "a": "the piece built by 1 and x", "w": ["the line through x", "the piece built by x and y", "the line through 1"], "why": "Under the dot of lists of n numbers."}, {"q": "Σeᵢ = 0 for the misses of the best line says what?", "a": "the miss is ⊥ 1", "w": ["the miss is ⊥ x", "the miss is 0", "the line passes through 0"], "why": "And Σxᵢeᵢ = 0 says the miss is ⊥ x."}, {"q": "Does the best line show that x causes y?", "a": "no: it is a shadow, a fact about lists", "w": ["yes, when r > 0", "yes, by the residuals technique", "only for many points"], "why": "y causing x, or a third list, gives the same shadow."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["31c"]=[{"q": "How is w₂ built from v₂ and e₁?", "a": "v₂ − ⟨v₂, e₁⟩e₁", "w": ["v₂ − e₁", "v₂ + ⟨v₂, e₁⟩e₁", "⟨v₂, e₁⟩e₁"], "why": "The miss of v₂ from its shadow on e₁."}, {"q": "Why is wₖ never 0 when straightening a free list?", "a": "vₖ would lie in the space of the earlier vⱼ", "w": ["products are positive", "eₖ has size 1", "the list is right-angled"], "why": "Free lists have no such vₖ."}, {"q": "The straightened powers 1, x, x² on [−1, 1], up to size, are what?", "a": "1, x, x² − 1/3", "w": ["1, x, x² − 1/2", "1, x − 1/2, x²", "1, x, x² + 1/3"], "why": "⟨x², 1⟩ = 2/3 and ‖1‖² = 2."}, {"q": "Why does the closest cubic keep the parabola’s first three readings?", "a": "e₄ is ⊥ e₁, e₂, e₃", "w": ["cubics contain parabolas", "the readings are free", "x³ is odd"], "why": "Shadow-sum readings do not change when a ⊥ vector is added."}, {"q": "A line reads X = QR. Which technique?", "a": "column-straightening", "w": ["straightening", "spectral", "turn-stretch-turn"], "why": "Q with right-angled columns, R a staircase."}, {"q": "What sits in place (i, k) of R, for i < k?", "a": "⟨vₖ, eᵢ⟩", "w": ["⟨vᵢ, eₖ⟩", "‖wₖ‖", "0"], "why": "The middle numbers are ‖wₖ‖."}, {"q": "XᵀXc = Xᵀy with X = QR becomes what?", "a": "Rc = Qᵀy", "w": ["Qc = Rᵀy", "Rᵀc = y", "QRc = y"], "why": "XᵀX = RᵀR; Rᵀ is undoable."}, {"q": "Q has fewer columns than rows. What is QQᵀ?", "a": "the shadow map onto Q’s columns", "w": ["I", "0", "QᵀQ"], "why": "QᵀQ = I, but QQᵀ keeps only the column space."}, {"q": "Straighten (3, 4) and (1, 0). What is e₁?", "a": "(0.6, 0.8)", "w": ["(3, 4)", "(0.8, 0.6)", "(1, 0)"], "why": "(3, 4)/5."}, {"q": "Why is w₂ = v₂ − ⟨v₂, v₁⟩v₁ wrong when ‖v₁‖ ≠ 1?", "a": "the shadow needs division by ‖v₁‖²", "w": ["v₁ is not free", "the product is not straight", "w₂ would be 0"], "why": "Without it the miss is not ⊥ v₁."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["31d"]=[{"q": "A real grid is symmetric under the dot when what holds?", "a": "Aᵀ = A", "w": ["A² = A", "AᵀA = I", "det A ≠ 0"], "why": "⟨Ax, y⟩ = ⟨x, Ay⟩."}, {"q": "A line reads: every stretch of a symmetric map is real. Which technique?", "a": "real-stretches", "w": ["right-angled-stretches", "spectral", "product-keeper"], "why": "λ⟨v, v⟩ = λ̄⟨v, v⟩."}, {"q": "A symmetric map stretches u by 2 and v by 5. What is ⟨u, v⟩?", "a": "0", "w": ["10", "7", "3"], "why": "Right-angled-stretches: different stretches, right angles."}, {"q": "A = QDQᵀ for symmetric A. What are the columns of Q?", "a": "a right-angled basis of axes", "w": ["the rows of A", "any free list", "the stretches"], "why": "The spectral technique."}, {"q": "What are the stretches of [[2, 1], [1, 2]]?", "a": "3 and 1", "w": ["2 and 2", "3 and −1", "4 and 1"], "why": "Axes (1, 1) and (1, −1)."}, {"q": "Why does a symmetric A keep the space ⊥ e₁?", "a": "⟨Av, e₁⟩ = ⟨v, Ae₁⟩ = λ₁⟨v, e₁⟩ = 0", "w": ["A is a length-keeper", "det A ≠ 0", "e₁ has size 1"], "why": "So the proof runs again inside it."}, {"q": "When does U keep every product?", "a": "U*U = I", "w": ["U = Uᵀ", "det U = 1", "U² = I"], "why": "Product-keeper; U* is the conjugate transpose."}, {"q": "Every stretch of a product-keeper has what size?", "a": "1", "w": ["0", "its determinant", "any size"], "why": "‖Uv‖ = ‖v‖ = |λ| ‖v‖."}, {"q": "What are the stretches of the quarter turn?", "a": "i and −i", "w": ["1 and −1", "0 and 1", "none at all"], "why": "It keeps lengths but is not symmetric."}, {"q": "[[1, 1], [0, 1]] has how many free stretched vectors?", "a": "one", "w": ["two", "none", "endlessly many free ones"], "why": "Not symmetric: no basis of axes."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["31e"]=[{"q": "Why may A in q = xᵀAx be taken symmetric?", "a": "(A + Aᵀ)/2 gives the same q", "w": ["every grid is symmetric", "q is positive", "A is square"], "why": "xᵀAx = xᵀAᵀx."}, {"q": "A line reads q = λ₁y₁² + ⋯ + λₙyₙ², y = Qᵀx. Which technique?", "a": "axes-form", "w": ["sign-count", "form-test", "hug-axes"], "why": "A quadratic form read along A’s axes."}, {"q": "2x₁² + 2x₁x₂ + 2x₂² = 2(x₁ + ½x₂)² + (3/2)x₂². What is fixed?", "a": "two positive numbers in front", "w": ["the numbers 2 and 3/2", "the numbers 3 and 1", "one positive, one negative"], "why": "Sign-count: the signs, not the numbers."}, {"q": "When is [[p, s], [s, r]] positive definite?", "a": "p > 0 and pr − s² > 0", "w": ["pr − s² > 0", "p > 0 and r > 0", "p + r > 0"], "why": "Form-test, n = 2."}, {"q": "Why is det A > 0 not enough?", "a": "two negative stretches multiply to a positive", "w": ["det can be 0", "A may not be symmetric", "it is enough"], "why": "−I has det 1 and is negative definite."}, {"q": "At a flat point H has stretches 3 and −2. What is the point?", "a": "a saddle", "w": ["a bottom", "a top", "no verdict"], "why": "Hug-axes: both signs."}, {"q": "At a flat point H has stretches 2 and 0. What does the test say?", "a": "nothing", "w": ["a bottom", "a saddle", "a top"], "why": "Along the 0 axis the hug is flat and the remainder decides."}, {"q": "x² + 3xy + y² at (0, 0)?", "a": "a saddle", "w": ["a bottom", "a top", "flat"], "why": "H = [[2, 3], [3, 2]], stretches 5 and −1."}, {"q": "What does the hug-axes technique give in three variables that 28l2 could not?", "a": "a verdict from the stretches of H", "w": ["nothing new", "the value at the point", "a slope"], "why": "28l2’s letters are for two variables."}, {"q": "In the sign-count proof, why do U and U′ share a vector ≠ 0?", "a": "their dimensions add past n", "w": ["both contain 0", "both are closed", "q is positive"], "why": "p + (n − p′) > n if p > p′."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["31f"]=[{"q": "Why are the stretches of AᵀA never below 0?", "a": "vᵀAᵀAv = |Av|² ≥ 0", "w": ["AᵀA is a length-keeper", "A is square", "det AᵀA > 0"], "why": "Never-negative."}, {"q": "What are the stretch sizes of A?", "a": "the roots of the stretches of AᵀA", "w": ["the stretches of A", "the entries of A", "the roots of A’s entries"], "why": "σₖ = √λₖ(AᵀA)."}, {"q": "A line reads A = UΣVᵀ. Which technique?", "a": "turn-stretch-turn", "w": ["spectral", "column-straightening", "keep-the-largest"], "why": "Avₖ = σₖuₖ with right-angled bases."}, {"q": "How is uₖ found, for σₖ > 0?", "a": "Avₖ/σₖ", "w": ["vₖ/σₖ", "Aᵀvₖ", "σₖvₖ"], "why": "Then the uₖ are at right angles."}, {"q": "What is ‖A‖ for A = [[3, 0], [4, 5]]?", "a": "√45", "w": ["5", "45", "√50"], "why": "AᵀA has stretches 45 and 5."}, {"q": "A line reads |Ax| ≤ σ₁|x|. Which technique?", "a": "greatest-stretch", "w": ["keep-the-largest", "never-negative", "product-bound"], "why": "Equality at x = v₁."}, {"q": "‖A − Aᵣ‖ equals what?", "a": "σᵣ₊₁", "w": ["σᵣ", "σ₁", "σᵣ₊₁²"], "why": "Keep-the-largest; no simpler grid is closer."}, {"q": "[[0, 2], [0, 0]]: stretches and stretch sizes?", "a": "stretches 0, 0; sizes 2, 0", "w": ["both 2, 0", "stretches 2, 0; sizes 0, 0", "both 0, 0"], "why": "Stretches are not stretch sizes."}, {"q": "A table 1000 × 1000 kept to its 20 largest pieces needs how many numbers?", "a": "40 020", "w": ["20 000", "1 000 000", "20"], "why": "20 × (1000 + 1000 + 1)."}, {"q": "Is ‖A‖ the largest number in A?", "a": "no: [[1, 1], [1, 1]] has ‖A‖ = 2", "w": ["yes, always", "yes, for symmetric A", "no: it is the sum of the entries"], "why": "It is the most A lengthens a vector."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["31g"]=[{"q": "For f = x on [0, 1], what are ‖f‖∞, ‖f‖₁, ‖f‖₂?", "a": "1, 1/2, 1/√3", "w": ["1, 1/2, 1/3", "1/2, 1/2, 1/2", "1, 1, 1"], "why": "Highest height, total, energy."}, {"q": "Which line shows that no product gives ‖·‖∞?", "a": "the parallelogram line fails for x and 1 − x", "w": ["the triangle fails", "‖f‖∞ can be 0", "‖tf‖ ≠ |t| ‖f‖"], "why": "1 + 1 ≠ 2 + 2."}, {"q": "A line reads ‖f‖₁ ≤ ‖f‖₂ ≤ ‖f‖∞ on [0, 1]. Which technique?", "a": "size-order", "w": ["matched-powers", "sup-size", "size-complete"], "why": "On length L: √L and L appear."}, {"q": "When are p and q matched?", "a": "1/p + 1/q = 1", "w": ["p + q = 1", "pq = 1", "p = q"], "why": "Then ∫|fg| ≤ ‖f‖ₚ‖g‖_q."}, {"q": "h = 1 at ½ and 0 elsewhere. What is ‖h‖₁?", "a": "0", "w": ["1", "½", "not defined"], "why": "So the first demand of a size fails without the bend."}, {"q": "When are two sized functions taken as the same in L¹?", "a": "when they agree but for a set of size zero", "w": ["when their totals agree", "when they agree at every fraction", "when they agree at one point"], "why": "The same-members axiom, bent one level up."}, {"q": "What is the accepted name of the same-members axiom?", "a": "extensionality", "w": ["choice", "induction", "completeness"], "why": "From the Latin extensio."}, {"q": "Ramps climbing over [½, ½ + 1/n] crowd under ‖·‖₁. Where do they settle?", "a": "at a step, outside the continuous functions", "w": ["at a ramp", "at 0", "nowhere"], "why": "The continuous functions have holes."}, {"q": "A line reads: in L¹ every crowding list settles. Which technique?", "a": "size-complete", "w": ["sup-complete", "size-order", "size-zero-sameness"], "why": "With rung 30’s totals."}, {"q": "For f in L², is f(½) a number?", "a": "no: the box holds every value there", "w": ["yes", "only if f is bounded", "yes, its average"], "why": "Only claims totals can see survive."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["31h"]=[{"q": "What is ℓ²?", "a": "endless lists with Σ|cₖ|² finite", "w": ["endless lists of numbers", "lists of two numbers", "lists with finitely many places"], "why": "With ⟨c, d⟩ = Σcₖd̄ₖ."}, {"q": "A line reads: ℓ² is a complete product space. Which technique?", "a": "list-space", "w": ["energy-sum", "size-complete", "complete-closest"], "why": "Each place crowds, so settles."}, {"q": "A line reads Σ|⟨f, eₖ⟩|² ≤ ‖f‖². Which technique?", "a": "energy-bound", "w": ["energy-sum", "shadow-sum", "product-bound"], "why": "Readings never hold more energy than f."}, {"q": "When does a right-angled list rebuild every vector?", "a": "when it leaves no direction out", "w": ["always", "when it is endless", "when its readings settle"], "why": "Energy-sum; then ‖f‖² = Σ|⟨f, eₖ⟩|²."}, {"q": "What did completeness do in the energy-sum proof?", "a": "made the crowding running sums settle", "w": ["bounded the readings", "made the list right-angled", "nothing"], "why": "The energy bound makes them crowd."}, {"q": "A line reads: every f has one closest point in a closed W. Which technique?", "a": "complete-closest", "w": ["closest-point", "shadow-sum", "reading-is-product"], "why": "And f − w ⊥ W."}, {"q": "Where did the complete-closest proof use the parallelogram line?", "a": "to show the nearer points crowd", "w": ["to find d", "to show W is closed", "it did not"], "why": "Only sizes from a product obey it."}, {"q": "Is (1, 1/√2, 1/√3, …) in ℓ²?", "a": "no: Σ1/k is not finite", "w": ["yes", "yes: its terms head to 0", "only up to its first term"], "why": "Heading to 0 is not enough."}, {"q": "A right-angled list leaves a direction out. Does the energy sum hold?", "a": "no: some f ≠ 0 has every reading 0", "w": ["yes, always", "yes, by the energy bound", "only for f = 0"], "why": "Its readings sum to 0 ≠ ‖f‖²."}, {"q": "When is a space W inside a product space closed?", "a": "every list in W that settles settles in W", "w": ["W is finite", "W is a basis", "W holds 0"], "why": "Defined on 31h4."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["31i"]=[{"q": "What is a complete space with a size?", "a": "a space with a size in which every crowding list settles", "w": ["a space with a product", "a space of continuous functions", "a finite space"], "why": "No product needed."}, {"q": "A line reads: continuous functions on [u, v] under ‖·‖∞ are complete. Which technique?", "a": "sup-complete", "w": ["size-complete", "list-space", "size-sum"], "why": "Settling at every input at once keeps continuity."}, {"q": "Σ‖gₖ‖ settles in a complete space. What then?", "a": "Σgₖ settles", "w": ["Σgₖ is 0", "every gₖ is 0", "nothing"], "why": "Size-sum."}, {"q": "When is a straight map L bounded?", "a": "‖Lf‖ ≤ C‖f‖ for some C and every f", "w": ["L is continuous at 0 only", "‖Lf‖ ≤ ‖f‖ for some f", "L has finitely many values"], "why": "The least C is ‖L‖."}, {"q": "A line reads: L is continuous exactly when bounded. Which technique?", "a": "bounded-is-continuous", "w": ["reading-is-product", "sup-complete", "size-sum"], "why": "For straight maps between spaces with sizes."}, {"q": "Is f ↦ f′ bounded under ‖·‖∞?", "a": "no: sin(nx)/n heads to 0, its slopes do not", "w": ["yes, by 1", "yes, by 2π", "only on polynomials"], "why": "Slope roughens."}, {"q": "Is f ↦ ∫ᵤˣ f bounded under ‖·‖∞?", "a": "yes, by v − u", "w": ["no", "yes, by 1", "only for continuous f"], "why": "Area smooths."}, {"q": "In a complete product space, every bounded reading is what?", "a": "a product with one vector g", "w": ["a slope", "a value at a point", "a sum of values"], "why": "Reading-is-product; ‖φ‖ = ‖g‖."}, {"q": "The reading f ↦ ∫₀¹ x f(x) dx on L² is the product with which g?", "a": "x", "w": ["1", "x²", "1/x"], "why": "Its stretch size is 1/√3."}, {"q": "Why is f ↦ f(½) not a product in L²?", "a": "it is not bounded under ‖·‖₂", "w": ["it is not straight", "L² has holes", "f(½) is always 0"], "why": "Narrow tents: height n, energy near 0."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["31j"]=[{"q": "What is Bₙf(x)?", "a": "the average of f at the share of heads", "w": ["f at n random points", "the polynomial through n points", "the shadow of f on xⁿ"], "why": "Σ f(k/n) C(n, k) xᵏ(1 − x)ⁿ⁻ᵏ."}, {"q": "What is the spread of S/n, n coins heads with chance x?", "a": "x(1 − x)/n", "w": ["x/n", "x(1 − x)", "1/n"], "why": "At most 1/(4n)."}, {"q": "What is Bₙx²?", "a": "x² + x(1 − x)/n", "w": ["x²", "x² − x/n", "x/n"], "why": "E Y² = (E Y)² + Var Y."}, {"q": "A line reads ‖Bₙf − f‖∞ → 0. Which technique?", "a": "average-polynomial", "w": ["coin-average", "zigzag-sum", "through-the-points"], "why": "For continuous f on [0, 1]."}, {"q": "What does even continuity do in that proof?", "a": "gives one δ for every x at once", "w": ["bounds the spread", "makes Bₙf a polynomial", "makes f bounded"], "why": "Loose, then locked."}, {"q": "Is Bₙf random?", "a": "no: it is an average over every outcome", "w": ["yes", "only for odd n", "only at x = ½"], "why": "No coin is tossed."}, {"q": "W = Σz(4ᵏx)/2ᵏ. Which technique makes it continuous?", "a": "size-sum, in the sup-complete space", "w": ["average-polynomial", "size-order", "energy-sum"], "why": "The highest heights add to 1."}, {"q": "Does W have a slope anywhere?", "a": "no", "w": ["yes, everywhere but the corners", "yes, at fractions", "yes, at 0"], "why": "The chord slopes jump by 2ᵐ⁺¹."}, {"q": "Can polynomials come within any ε of W at every input?", "a": "yes", "w": ["no: W has no slope", "only in energy size", "only near 0"], "why": "Average-polynomial needs only continuity."}, {"q": "Can a step on [0, 1] be within ¼ of a polynomial everywhere?", "a": "no", "w": ["yes", "yes, for n large", "only in total size"], "why": "A polynomial cannot jump the gap of ½."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["31k"]=[{"q": "What is the normal of a plane through 0?", "a": "a vector ⊥ every vector of the plane", "w": ["any vector in the plane", "the closest point", "a right-angled list"], "why": "Through-the-normal uses it."}, {"q": "Shadow of f on the plane ⊥ n?", "a": "f − ((f · n)/|n|²)n", "w": ["((f · n)/|n|²)n", "f − (f · n)n", "f + n"], "why": "Drop the part along n."}, {"q": "Distance from (4, 1, 5) to 2x − y + 2z = 6?", "a": "11/3", "w": ["17/3", "6", "11/9"], "why": "|17 − 6|/3."}, {"q": "In the power-columns fit, what is in place (j, k) of XᵀX?", "a": "Σxᵢ^(j+k)", "w": ["Σxᵢʲ Σxᵢᵏ", "xⱼxₖ", "Σxᵢ^(jk)"], "why": "Only sums of powers are needed."}, {"q": "Best line through 0, y ≈ bx: what is b?", "a": "Σxᵢyᵢ/Σxᵢ²", "w": ["ȳ/x̄", "Σyᵢ/Σxᵢ", "Sxy/Sxx"], "why": "Through-zero."}, {"q": "A reading has spread σᵢ². What is its weight?", "a": "1/σᵢ²", "w": ["1/σᵢ", "σᵢ²", "1"], "why": "Weighted-shadow."}, {"q": "A line reads XᵀWXc = XᵀWy. Which technique?", "a": "weighted-shadow", "w": ["power-columns", "through-zero", "through-the-normal"], "why": "The shadow under the weighted product."}, {"q": "Can a quadratic fit be done one column at a time?", "a": "no: the columns are not ⊥", "w": ["yes, always", "yes, if the points are even", "only for lines"], "why": "Fit together or straighten first."}, {"q": "Does forcing a line through 0 ever make the misses smaller?", "a": "no: it is a shadow on a smaller piece", "w": ["yes, sometimes", "yes, always", "only with weights"], "why": "A smaller piece is never closer."}, {"q": "Three columns and three points: what are the misses?", "a": "all 0", "w": ["all equal", "their average is 0", "undefined"], "why": "The piece is the whole space."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["31l"]=[{"q": "r is the cosine of which angle?", "a": "between the deviation vectors u and v", "w": ["between the best line and the x-axis", "between x and y themselves", "between the two fitted lines"], "why": "Correlation-angle."}, {"q": "r = 0.6. What share of the spread of y does the line take?", "a": "36%", "w": ["60%", "6%", "64%"], "why": "r²."}, {"q": "r = 0. What angle?", "a": "90°", "w": ["0°", "45°", "180°"], "why": "Right angles."}, {"q": "What do the two slopes b and b′ multiply to?", "a": "r²", "w": ["1", "r", "1/r²"], "why": "Two-lines technique."}, {"q": "In standard units, x is 2 widths up and r = 0.5. Predicted y?", "a": "1 width up", "w": ["2 widths up", "0.5 widths up", "4 widths up"], "why": "r times the units of x."}, {"q": "A line reads r_xy·w = (r_xy − r_xw r_yw)/√((1 − r_xw²)(1 − r_yw²)). Which technique?", "a": "take-out", "w": ["two-lines", "correlation-angle", "product-bound"], "why": "The angle between the misses."}, {"q": "r_xy = 0.6, r_xw = 0.8, r_yw = 0.75. Take-out correlation?", "a": "0", "w": ["0.6", "0.36", "0.2"], "why": "0.6 − 0.6 = 0."}, {"q": "Can a fitted line show that no third list explains a link?", "a": "no", "w": ["yes, if r is high", "yes, with many points", "yes, by taking out w"], "why": "Only measured lists can be taken out."}, {"q": "Width of r from 30 bell-shaped pairs with r = 0.6?", "a": "about 0.12", "w": ["about 0.6", "about 0.02", "about 0.36"], "why": "(1 − 0.36)/√30."}, {"q": "x = −1, 0, 1 and y = x². What is r?", "a": "0", "w": ["1", "−1", "0.5"], "why": "Fixed by x, yet r = 0."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["31m"]=[{"q": "How many polynomials of degree at most n pass through n + 1 points with different inputs?", "a": "exactly one", "w": ["none", "n", "endlessly many"], "why": "Through-the-points."}, {"q": "Through (0, 1), (1, 3), (2, 7)?", "a": "1 + x + x²", "w": ["1 + 2x", "1 + 3x", "2x² + 1"], "why": "Lagrange pieces."}, {"q": "In f − p = f⁽ⁿ⁺¹⁾(ξ)/(n + 1)! · ω(x), which part depends only on the points?", "a": "ω(x)", "w": ["f⁽ⁿ⁺¹⁾(ξ)", "(n + 1)!", "ξ"], "why": "The product of distances."}, {"q": "For even points, where is |ω| largest?", "a": "near the ends", "w": ["in the middle", "at the points", "it is level"], "why": "The wiggle at the ends."}, {"q": "A line reads xpₙ = pₙ₊₁ + βₙpₙ + γₙpₙ₋₁. Which technique?", "a": "three-term", "w": ["through-the-points", "cosine-points", "straightening"], "why": "Each new member needs only the last two."}, {"q": "Tₙ(cos θ) = ?", "a": "cos nθ", "w": ["cosⁿθ", "n cos θ", "sin nθ"], "why": "The cosine polynomials, on this step."}, {"q": "Tₙ₊₁ = ?", "a": "2xTₙ − Tₙ₋₁", "w": ["xTₙ − Tₙ₋₁", "2xTₙ + Tₙ₋₁", "Tₙ + Tₙ₋₁"], "why": "From 21k."}, {"q": "The cosine points make max |ω| on [−1, 1] equal to what?", "a": "2⁻ⁿ", "w": ["1/n", "2ⁿ", "1/(n + 1)!"], "why": "Cosine-points."}, {"q": "More even points for 1/(1 + 25x²): 5, 11, 17. Largest misses?", "a": "0.44, 1.92, 14.4", "w": ["0.44, 0.11, 0.03", "falling to 0", "all 0.44"], "why": "More even points can be worse."}, {"q": "Is reading a table far past its last entry safe?", "a": "no: ω grows like a power of the distance", "w": ["yes, if the table is smooth", "yes, by the three-term technique", "yes, for cosine points"], "why": "Outside the points nothing pins p."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["31n"]=[{"q": "Applying A again and again, the error shrinks by what each step?", "a": "|λ₂/λ₁|", "w": ["|λ₁/λ₂|", "1/2", "|λ₂|"], "why": "27l2, cut to size at each step."}, {"q": "What is the two-sided reading R(x)?", "a": "xᵀAx/xᵀx", "w": ["|Ax|/|x|", "xᵀx", "det A"], "why": "Error the square of the vector’s."}, {"q": "A line reads |R(x) − λ| ≤ (λmax − λmin) sin²ε. Which technique?", "a": "two-sided-reading", "w": ["near-shift", "same-stretches", "powers-in-QR"], "why": "For symmetric A."}, {"q": "The stretches of (A − sI)⁻¹ are what?", "a": "1/(λ − s)", "w": ["λ − s", "s/λ", "λ + s"], "why": "Largest for λ nearest s."}, {"q": "Why are the digits lost in solving with A − sI harmless?", "a": "they point along the wanted axis", "w": ["the machine keeps all digits", "A is symmetric", "they cancel"], "why": "The danger and the purpose are the same."}, {"q": "One step of straighten-then-multiply-back?", "a": "Aₖ = QₖRₖ, Aₖ₊₁ = RₖQₖ", "w": ["Aₖ₊₁ = QₖRₖ", "Aₖ₊₁ = Qₖ²", "Aₖ₊₁ = RₖᵀRₖ"], "why": "Multiply back in the other order."}, {"q": "A line reads Aₖ₊₁ = QₖᵀAₖQₖ. Which technique?", "a": "same-stretches", "w": ["powers-in-QR", "near-shift", "column-straightening"], "why": "A turn keeps the stretches."}, {"q": "(Q₀⋯Qₖ₋₁)(Rₖ₋₁⋯R₀) equals what?", "a": "Aᵏ", "w": ["A", "I", "Aₖ"], "why": "Powers-in-QR."}, {"q": "Why not find stretches from det(A − λI) by machine?", "a": "small errors in its numbers move roots far", "w": ["it has no roots", "it is not a polynomial", "it is too short"], "why": "The numbers are huge."}, {"q": "When does again-and-again fail?", "a": "two stretches share the largest size, or c₁ = 0", "w": ["when A is symmetric", "when A is large", "never"], "why": "The swap grid never settles."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["31o"]=[{"q": "What is the spread grid C?", "a": "XᵀX/n, average taken away", "w": ["XXᵀ", "the grid of averages", "X/n"], "why": "Co-spreads, spreads down the middle."}, {"q": "Spread of the points along d of size 1?", "a": "dᵀCd", "w": ["|Cd|", "d · C", "tr C"], "why": "Spread-along."}, {"q": "Direction of most spread?", "a": "the axis of C’s largest stretch", "w": ["the first place", "the average", "the line of y on x"], "why": "Most-spread."}, {"q": "The spreads along all axes add to what?", "a": "the middle sum of C", "w": ["1", "λ₁", "det C"], "why": "The total spread."}, {"q": "Why do two different components never co-spread?", "a": "e₁ᵀCe₂ = λ₂ e₁ · e₂ = 0", "w": ["C is diagonal", "the average is 0", "they are independent"], "why": "Right-angled axes."}, {"q": "Least total squared distance to a flat piece of dimension r?", "a": "n(λᵣ₊₁ + ⋯ + λₚ)", "w": ["nλᵣ", "λ₁ + ⋯ + λᵣ", "n tr C"], "why": "Closest-piece."}, {"q": "Which technique gives 0 ≤ wⱼ ≤ 1 in that proof?", "a": "energy-bound (31h2)", "w": ["shadow-sum", "square-sum", "spectral"], "why": "eⱼ read along the list dₖ."}, {"q": "Four points (3, 1), (−3, −1), (1, 1), (−1, −1). Share on the first axis?", "a": "about 97%", "w": ["about 83%", "50%", "100%"], "why": "5.83 of 6."}, {"q": "Change claw size to millimetres. What changes?", "a": "C, and so the axes", "w": ["nothing", "only the stretches", "only the average"], "why": "Units are a choice; report it."}, {"q": "Is the first axis the line of y on x?", "a": "no: it makes misses at right angles least", "w": ["yes", "yes, in standard units", "only for two numbers"], "why": "Different shadows."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["31·then"]=[{"q": "Why fit the reading on the strength in a calibration?", "a": "the strengths are exact; the readings wobble", "w": ["readings are larger numbers", "it gives a steeper line", "strengths wobble more"], "why": "The misses belong to the readings."}, {"q": "Standards 0 to 8 mg/L, b = 0.0975, c = 0.016. Read back y₀ = 0.50.", "a": "about 4.96 mg/L", "w": ["about 5.0 exactly", "about 0.064", "about 4.6"], "why": "x₀ = (y₀ − c)/b."}, {"q": "Which term of the read-back width never shrinks with more standards?", "a": "the 1, the unknown’s own wobble", "w": ["1/n", "(y₀ − ȳ)²", "σ/b"], "why": "Average several readings of the unknown instead."}, {"q": "A raw straight line through mouse to elephant gives the mouse what?", "a": "about 42 W", "w": ["about 0.2 W", "about 3.4 W", "0 W"], "why": "The elephant rules the squares."}, {"q": "Fitting ln R against ln M misses each reading by what?", "a": "a share", "w": ["an amount", "a fixed watt", "nothing"], "why": "Log-fit."}, {"q": "Seven animals in logs: fitted power?", "a": "about 0.748", "w": ["about 0.667", "exactly 1", "about 0.5"], "why": "The three-quarter line."}, {"q": "Why is the plain average of Rᵢ/R̂ᵢ at least 1?", "a": "eᵗ ≥ 1 + t and the log misses add to 0", "w": ["the curve is too high", "logs are positive", "by chance"], "why": "The fit runs through the middle of the shares."}, {"q": "Ranks 1 to 10 000: how many lie between 1000 and 10 000?", "a": "9000", "w": ["1000", "3", "9"], "why": "The last tenth of the axis in logs."}, {"q": "A line reads Σₘ¹⁰ᵐ⁻¹ 1/k → ln 10. Which technique?", "a": "equal-decades", "w": ["log-fit", "read-back", "weighted-shadow"], "why": "Weights 1/k give each decade the same say."}, {"q": "Straight on log–log axes over three decades: a power law?", "a": "not shown: a few stretches cannot pin a curve", "w": ["yes", "yes, if the slope is −1", "yes, with weights"], "why": "It is a claim about the stretches seen."}];
