(function(C){C["31a"]=(C["31a"]||[]).concat([{"q": "Is ‖f + g‖ = ‖f‖ + ‖g‖ for every f and g?", "a": "no: only when one is a non-negative multiple of the other", "w": ["yes, when they are at right angles", "yes", "no: never"], "why": "Product-triangle technique: ‖f + g‖ ≤ ‖f‖ + ‖g‖."}, {"q": "Does ⟨f, g⟩ = 0 give f = 0 or g = 0?", "a": "no: 1 and x on [−1, 1] are at right angles and neither is 0", "w": ["no: it gives f = g", "yes", "yes, for functions"], "why": "⟨f, g⟩ = 0 says at right angles."}, {"q": "When is |⟨f, g⟩| = ‖f‖ ‖g‖?", "a": "exactly when one of f and g is a multiple of the other", "w": ["always", "never", "exactly when they are at right angles"], "why": "Product-bound technique."}, {"q": "f and g are at right angles. What is ‖f + g‖²?", "a": "‖f‖² + ‖g‖²", "w": ["(‖f‖ + ‖g‖)²", "‖f‖² − ‖g‖²", "2‖f‖ ‖g‖"], "why": "Square-sum technique."}, {"q": "Is ⟨f, tg⟩ = t⟨f, g⟩ for a turning number t?", "a": "no: the second slot turns t to its conjugate, t̄⟨f, g⟩", "w": ["yes", "no: it is |t|⟨f, g⟩", "yes, in both slots"], "why": "Turned-product technique."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["31b"]=(C["31b"]||[]).concat([{"q": "Is Pf = Σ⟨f, vₖ⟩vₖ for any basis vₖ?", "a": "no: the shadow-sum needs a right-angled list; otherwise solve Gc = b", "w": ["yes", "yes, when the vₖ are free", "no: no basis gives it"], "why": "Miss-at-right-angles technique."}, {"q": "Does the best line through the data show that x causes y?", "a": "no: a shadow is geometry; it says nothing about why the vectors point where they do", "w": ["yes, when the miss is small", "no: it shows that y causes x", "yes"], "why": "A closest point is a fact about distances."}, {"q": "To what is the miss f − Pf at right angles?", "a": "to every vector of W", "w": ["to nothing", "to e₁ only", "to f"], "why": "Shadow-sum technique."}, {"q": "Is the closest point of the line through g always ⟨f, g⟩g?", "a": "no: only when ‖g‖ = 1; in general (⟨f, g⟩/‖g‖²)g", "w": ["yes", "no: it is ⟨f, g⟩f", "no: it is g/‖g‖"], "why": "Closest-point technique: ‖e‖ = 1."}, {"q": "Is any other point of W as close to f as Pf?", "a": "no: Pf is the one closest point", "w": ["yes: every point of the line through Pf", "it depends on f", "yes: its mirror point"], "why": "Shadow-sum technique: no other point of W is as close."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["31c"]=(C["31c"]||[]).concat([{"q": "Is w₂ = v₂ − ⟨v₂, v₁⟩v₁?", "a": "only when ‖v₁‖ = 1; in general take away ⟨v₂, v₁⟩v₁/‖v₁‖²", "w": ["no: take away ⟨v₁, v₁⟩v₂", "yes, always", "no: add the shadow"], "why": "The shadow on v₁ needs v₁ cut to size 1."}, {"q": "Is QQᵀ = I for every Q with right-angled columns?", "a": "no: only when Q is square; with fewer columns QQᵀ is the shadow map onto what they build", "w": ["yes", "no: and QᵀQ fails too", "yes, when Q has more rows than columns"], "why": "QᵀQ = I always; QQᵀ only for a square Q."}, {"q": "What do the first k straightened vectors build?", "a": "the same space as v₁, …, vₖ", "w": ["a line", "the whole space", "the space of vₖ alone"], "why": "Straightening technique."}, {"q": "Does straightening in another order give the same list?", "a": "no: the first vector decides the first direction; other orders give other lists", "w": ["no: other orders fail", "yes, the same vectors in another order", "yes"], "why": "Straightening technique."}, {"q": "Is w₃ = v₃ − ⟨v₃, e₂⟩e₂?", "a": "no: the shadows on every earlier e are taken away, not only the last", "w": ["no: only the shadow on e₁", "yes, when e₁ and e₂ are at right angles", "yes"], "why": "Straightening technique."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["31d"]=(C["31d"]||[]).concat([{"q": "U keeps every product. What size has every stretch of U?", "a": "1", "w": ["any size", "above 1", "0"], "why": "Product-keeper technique."}, {"q": "Is QᵀAQ = D for any length-keeper Q?", "a": "no: only for the Q whose columns are A’s axes", "w": ["no: for no Q", "yes, when A is symmetric", "yes"], "why": "The columns of Q are the stretched vectors of A."}, {"q": "Do equal stretches give vectors at right angles?", "a": "not by the technique: it needs λ ≠ μ; with a repeated stretch, choose right angles inside its space", "w": ["yes, when the map is a length-keeper", "no: they are never at right angles", "yes"], "why": "Right-angled-stretches technique."}, {"q": "Has every real grid a real stretch?", "a": "no: the quarter turn has stretches i and −i", "w": ["yes, when it is square", "no: only symmetric grids have stretches", "yes"], "why": "Real-stretches technique: a symmetric map."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["31e"]=(C["31e"]||[]).concat([{"q": "Written as a sum of squares, are the numbers in front fixed, as well as their signs?", "a": "no: only the counts of signs are; 3 and 1 along the axes, 2 and 3/2 by completing the square", "w": ["yes", "no: the signs change too", "yes, up to their order"], "why": "Sign-count technique."}, {"q": "det A > 0. Is q positive definite?", "a": "no: −x₁² − x₂² has det 1 and is below 0 everywhere but 0", "w": ["yes", "yes, for n = 2", "no: det A must be below 0"], "why": "Form-test technique: p > 0 and pr − s² > 0."}, {"q": "A stretch of H is 0. Is the flat point a saddle?", "a": "not always: x² + y⁴ has H with a stretch 0 and a bottom", "w": ["yes", "no: it is always a bottom", "no: it is always a top"], "why": "Hug-axes technique: it speaks only when no stretch is 0."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["31f"]=(C["31f"]||[]).concat([{"q": "How close to A can a grid come that reaches at most r dimensions?", "a": "no closer than σᵣ₊₁", "w": ["as close as you like", "no closer than σ₁", "no closer than σᵣ"], "why": "Keep-the-largest technique."}, {"q": "What is the most A lengthens any vector?", "a": "σ₁", "w": ["σ₁ + σ₂ + ⋯", "the largest number in A", "σ₁²"], "why": "Greatest-stretch technique."}, {"q": "Is Aᵣ the grid A with all but r rows set to 0?", "a": "no: Aᵣ keeps the r largest pieces σₖuₖvₖᵀ, which spread over every row", "w": ["yes, when A is square", "no: all but r columns", "yes"], "why": "Keep-the-largest technique."}, {"q": "Is U = V in every turn-stretch-turn?", "a": "no: only for symmetric A with stretches ≥ 0", "w": ["no: never", "yes, when A is square", "yes"], "why": "Turn-stretch-turn technique."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["31g"]=(C["31g"]||[]).concat([{"q": "On [0, 1], how are the three sizes ordered?", "a": "‖f‖₁ ≤ ‖f‖₂ ≤ ‖f‖∞", "w": ["they are equal", "‖f‖∞ ≤ ‖f‖₂ ≤ ‖f‖₁", "‖f‖₂ ≤ ‖f‖₁ ≤ ‖f‖∞"], "why": "Size-order technique."}, {"q": "When are p and q matched?", "a": "when 1/p + 1/q = 1", "w": ["when pq = 1", "when p + q = 1", "when p = q"], "why": "Matched-powers technique: ∫|fg| ≤ ‖f‖ₚ ‖g‖_q."}, {"q": "Does ‖f‖₁ = 0 give f(x) = 0 for every x?", "a": "no: only but for size zero; h = 1 at ½ alone has ‖h‖₁ = 0", "w": ["yes", "yes, in L¹", "no: f can be 1 on an interval"], "why": "Size-zero-sameness technique."}, {"q": "Is ‖f‖∞ ≤ ‖f‖₁ on [0, 1]?", "a": "no: the tents have height n and total size 1", "w": ["yes", "yes, by the size-order technique", "no: the two are always equal"], "why": "Size-order technique: ‖f‖₁ ≤ ‖f‖₂ ≤ ‖f‖∞ on [0, 1]."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
